const pruneWikiVersions = `-- name: PruneWikiVersions :execrows
WITH ranked AS (
    SELECT v.id, v.created_at,
        row_number() OVER (ORDER BY v.created_at DESC, v.id DESC) AS n,
        row_number() OVER (PARTITION BY (v.created_at AT TIME ZONE 'UTC')::date ORDER BY v.created_at DESC, v.id DESC) AS day_n
    FROM wiki_page_versions v WHERE v.page_id = $2::uuid
)
DELETE FROM wiki_page_versions d USING ranked r
WHERE d.id = r.id
  AND (r.n > 200 OR (r.created_at < $1::timestamptz - interval '7 days' AND r.day_n > 1))
`

type PruneWikiVersionsParams struct {
	Now    time.Time
	PageID uuid.UUID
}

// Keeps ≤ 200 versions of a page (the newest) and, older than 7 days, only the newest of each
// UTC day.
func (q *Queries) PruneWikiVersions(ctx context.Context, arg PruneWikiVersionsParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneWikiVersions, arg.Now, arg.PageID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const reindexWikiSiblings = `-- name: ReindexWikiSiblings :exec
WITH ordered AS (
    SELECT s.id, (row_number() OVER (ORDER BY s.position, (s.id = $1::uuid) DESC, s.id) - 1)::int AS pos
    FROM wiki_pages s
    WHERE s.workspace_id = $2::uuid AND s.trashed_at IS NULL
      AND (s.parent_id = $3::uuid OR ($3::uuid IS NULL AND s.parent_id IS NULL))
)
UPDATE wiki_pages w SET position = ordered.pos
FROM ordered WHERE w.id = ordered.id AND w.position <> ordered.pos
`

type ReindexWikiSiblingsParams struct {
	FirstID     *uuid.UUID
	WorkspaceID uuid.UUID
	ParentID    *uuid.UUID
}

// Renumbers the live children of a parent (NULL = the top level) 0.. in their order; on a tie
// first_id goes first (the page just moved to that position pushes the others down).
func (q *Queries) ReindexWikiSiblings(ctx context.Context, arg ReindexWikiSiblingsParams) error {
	_, err := q.db.Exec(ctx, reindexWikiSiblings, arg.FirstID, arg.WorkspaceID, arg.ParentID)
	return err
}

const restoreWikiSubtree = `-- name: RestoreWikiSubtree :many
WITH RECURSIVE root AS (
    SELECT r.id, r.workspace_id, r.trashed_at FROM wiki_pages r WHERE r.id = $1::uuid AND r.trashed_root
), sub (id) AS (
    SELECT root.id FROM root
    UNION ALL
    SELECT c.id FROM wiki_pages c JOIN sub ON c.parent_id = sub.id
    WHERE NOT c.trashed_root AND c.trashed_at = (SELECT root.trashed_at FROM root)
), last AS (
    SELECT coalesce(max(s.position) + 1, 0)::int AS pos FROM wiki_pages s, root
    WHERE s.workspace_id = root.workspace_id AND s.trashed_at IS NULL
      AND (s.parent_id = $2::uuid OR ($2::uuid IS NULL AND s.parent_id IS NULL))
)
UPDATE wiki_pages w SET
    trashed_at   = NULL,
    trashed_by   = NULL,
    trashed_root = false,
    parent_id    = CASE WHEN w.id = $1::uuid THEN $2::uuid ELSE w.parent_id END,
    position     = CASE WHEN w.id = $1::uuid THEN (SELECT last.pos FROM last) ELSE w.position END,
    updated_at   = CASE WHEN w.id = $1::uuid THEN now() ELSE w.updated_at END
FROM sub WHERE w.id = sub.id
RETURNING w.id
`

type RestoreWikiSubtreeParams struct {
	ID       uuid.UUID
	ParentID *uuid.UUID
}

// Restores a trash root and the part of its subtree trashed with it (same trashed_at, not a
// root of its own). parent_id: where the root goes back (the caller picks the top level when the
// old parent is gone or in the trash); the root goes last among its new siblings (under
// LockWikiTree). Returns the ids.
func (q *Queries) RestoreWikiSubtree(ctx context.Context, arg RestoreWikiSubtreeParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, restoreWikiSubtree, arg.ID, arg.ParentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

