const wikiSearchHeadlines = `-- name: WikiSearchHeadlines :many
SELECT w.id, ts_headline('russian', coalesce(nullif(w.plain_text, ''), w.title),
    to_tsquery('russian', $1::text) || to_tsquery('simple', $1::text),
    $2::text)::text AS snippet
FROM wiki_pages w WHERE w.id = ANY($3::uuid[])
`

type WikiSearchHeadlinesParams struct {
	Tsq     string
	Options string
	Ids     []uuid.UUID
}

type WikiSearchHeadlinesRow struct {
	ID      uuid.UUID
	Snippet string
}

// The highlighted fragments of a page of search hits: of the text, else of the title
// (searchq.HeadlineOptions).
func (q *Queries) WikiSearchHeadlines(ctx context.Context, arg WikiSearchHeadlinesParams) ([]WikiSearchHeadlinesRow, error) {
	rows, err := q.db.Query(ctx, wikiSearchHeadlines, arg.Tsq, arg.Options, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WikiSearchHeadlinesRow{}
	for rows.Next() {
		var i WikiSearchHeadlinesRow
		if err := rows.Scan(&i.ID, &i.Snippet); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const wikiUpdatesSince = `-- name: WikiUpdatesSince :one
SELECT count(*)::int AS updates, coalesce(sum(octet_length(data)), 0)::bigint AS bytes,
    coalesce(array_agg(DISTINCT author_id) FILTER (WHERE author_id IS NOT NULL), '{}')::uuid[] AS authors
FROM wiki_page_updates
WHERE page_id = $1 AND seq > $2::bigint
`

type WikiUpdatesSinceParams struct {
	PageID   uuid.UUID
	AfterSeq int64
}

type WikiUpdatesSinceRow struct {
	Updates int32
	Bytes   int64
	Authors []uuid.UUID
}

// How many updates and bytes are stored after a seq: the COMPACT_REQUEST thresholds (> 500
// updates or > 1 MiB) and the authors of the next version.
func (q *Queries) WikiUpdatesSince(ctx context.Context, arg WikiUpdatesSinceParams) (WikiUpdatesSinceRow, error) {
	row := q.db.QueryRow(ctx, wikiUpdatesSince, arg.PageID, arg.AfterSeq)
	var i WikiUpdatesSinceRow
	err := row.Scan(&i.Updates, &i.Bytes, &i.Authors)
	return i, err
}
